				multiNestYAML := "receivers:\n  otlp: {}\nexporters:\n  bigquery: '${env:PR159_BODY_MULTI_NEST}'\nservice:\n  pipelines:\n    logs:\n      receivers: [otlp]\n      exporters: [bigquery]\n"
